describe('User Profile - Timezone Settings', () => {
    beforeEach(() => {
        cy.visit('/profile/settings');
        cy.login(); // Assuming there's a custom command for login
    });

    it('should successfully update the timezone to a valid option', () => {
        cy.get('select[name="timezone"]').select('GMT+0:00');
        cy.get('button[type="submit"]').click();
        cy.get('.notification').should('contain', 'Timezone updated successfully');
        cy.get('select[name="timezone"]').should('have.value', 'GMT+0:00');
    });

    it('should show an error when selecting an invalid timezone', () => {
        cy.get('select[name="timezone"]').select('Invalid/Timezone');
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('contain', 'Please select a valid timezone');
    });
});
